        int r = vfs_unlink(name);
        fs_witness_leave();
        if (g_debug_vfs)
            kprintf("[dbgvfs ] pid %u: SYS_VFS_UNLINK('%s') -> %d\n", kprocs[current_proc_idx].pid, name, r);
