static void cmd_about(void) {
    kprintf("Outrun OS kernel %s — memory-safe-by-design microkernel project\n", KERNEL_VERSION);
    kputs(
      "Booted via GRUB/Multiboot2, running in x86_64 long mode.\n"
      "This image: Assembly bootstrap + freestanding C core. Live subsystems:\n"
      "IDT/PIC/PIT interrupts, PS/2 + serial dual console, Multiboot2 memory\n"
      "map, and the capability table from the Outrun architecture running in\n"
      "kernel space. Next roadmap phases: user mode, ELF loading, and the\n"
      "shared-memory device regions proven in the userspace prototype.\n");
}
static void cmd_demo(void) {
    kputs("-- Outrun capability walk-through (kernel space) --\n");
    int d = cap_mint("camera-driver", "camera0", 'W');
    int a = cap_mint("stream-app",    "camera0", 'R');
    int g = cap_mint("gesture-svc",   "camera0", 'R');
    kputs("[captbl ] data path now belongs to the holders — kernel steps aside\n");
    cap_revoke(a);
    kputs("[captbl ] stream-app's next access check fails: mapping dead, no signal sent\n");
    cap_revoke(g);
    cap_revoke(d);
    kputs("-- demo complete: mint -> grant -> revoke, all unforgeable, all in-kernel --\n");
}

static void shell_exec(char *line) {
    /* tokenize in place */
    /* v0.57: 8, not 4 — `cc a.c b.c c.c -o out.elf` needs more than four
     * tokens, and a tokenizer that silently drops the tail would compile the
     * wrong set of files. */
    char *argv[8] = {0};
    int argc = 0;
    for (char *p = line; *p && argc < 8; ) {
        while (*p == ' ') p++;
        if (!*p) break;
        argv[argc++] = p;
        while (*p && *p != ' ') p++;
        if (*p) *p++ = 0;
    }
    if (argc == 0) return;

    if      (!kstrcmp(argv[0], "help"))   cmd_help();
    else if (!kstrcmp(argv[0], "about"))  cmd_about();
    else if (!kstrcmp(argv[0], "clear"))  vga_clear();
    else if (!kstrcmp(argv[0], "caps"))   cap_list();
    else if (!kstrcmp(argv[0], "demo"))   cmd_demo();
    else if (!kstrcmp(argv[0], "passthrough")) cmd_passthrough();
    else if (!kstrcmp(argv[0], "usermode")) cmd_usermode();
    else if (!kstrcmp(argv[0], "disk")) cmd_disk();
    else if (!kstrcmp(argv[0], "cas")) cmd_cas();
    else if (!kstrcmp(argv[0], "sched")) cmd_sched();
    else if (!kstrcmp(argv[0], "vfs")) cmd_vfs();
    else if (!kstrcmp(argv[0], "net")) cmd_net();
    else if (!kstrcmp(argv[0], "gfx")) cmd_gfx();
    else if (!kstrcmp(argv[0], "stream")) { ts_print_timeline(); ts_query("the Q3 chart Sarah sent"); }
    else if (!kstrcmp(argv[0], "validate")) cmd_validate();
    else if (!kstrcmp(argv[0], "invariants")) cmd_invariants();
    else if (!kstrcmp(argv[0], "stress")) cmd_stress();
    else if (!kstrcmp(argv[0], "fuzz")) cmd_fuzz();
    else if (!kstrcmp(argv[0], "sweep")) cmd_sweep();
    else if (!kstrcmp(argv[0], "iommu")) cmd_iommu();
    else if (!kstrcmp(argv[0], "capdma")) cmd_capdma();
    else if (!kstrcmp(argv[0], "nicdrv")) cmd_nicdriver();
    else if (!kstrcmp(argv[0], "canvas")) cmd_canvas(1000000, 0);
    else if (!kstrcmp(argv[0], "cursor")) cmd_cursor();
    else if (!kstrcmp(argv[0], "kinetic")) cmd_kinetic();
    else if (!kstrcmp(argv[0], "surface")) cmd_surface();
    else if (!kstrcmp(argv[0], "surfin")) cmd_surfin();
    else if (!kstrcmp(argv[0], "threads")) cmd_threads();
    else if (!kstrcmp(argv[0], "flip")) cmd_flip();
    else if (!kstrcmp(argv[0], "keys")) cmd_keys();
    else if (!kstrcmp(argv[0], "smp")) cmd_smp();
    else if (!kstrcmp(argv[0], "parallel") || !kstrcmp(argv[0], "par")) cmd_parallel();
    else if (!kstrcmp(argv[0], "audit")) cmd_audit();
    else if (!kstrcmp(argv[0], "mcsched")) cmd_mcsched();
    else if (!kstrcmp(argv[0], "mcq")) cmd_mcq();
    else if (!kstrcmp(argv[0], "mcpre")) cmd_mcpre();
    else if (!kstrcmp(argv[0], "slice")) cmd_slice();
    else if (!kstrcmp(argv[0], "cio")) cmd_cio();
    else if (!kstrcmp(argv[0], "smpstress")) cmd_smp_stress();
    else if (!kstrcmp(argv[0], "dmastress")) cmd_dma_stress();
    else if (!kstrcmp(argv[0], "leakcheck")) cmd_leakcheck();
    else if (!kstrcmp(argv[0], "kpstress")) cmd_kproc_stress();
    else if (!kstrcmp(argv[0], "ipcstress")) cmd_ipc_stress();
    else if (!kstrcmp(argv[0], "vfiostress")) cmd_vfio_stress();
    else if (!kstrcmp(argv[0], "vfsstress")) cmd_vfs_stress();
    else if (!kstrcmp(argv[0], "gpustress")) cmd_gpu_stress();
    else if (!kstrcmp(argv[0], "audiostress")) cmd_audio_stress();
    else if (!kstrcmp(argv[0], "netstress")) cmd_net_stress();
    else if (!kstrcmp(argv[0], "wimpstress")) cmd_wimp_stress();
    else if (!kstrcmp(argv[0], "usersstress")) cmd_users_stress();
    else if (!kstrcmp(argv[0], "authstress")) cmd_auth_stress();   /* v0.74 — see boot sequence */
    else if (!kstrcmp(argv[0], "shastress"))  cmd_sha_stress();    /* v0.75 — SHA-256 vectors */
    else if (!kstrcmp(argv[0], "udbpersist")) cmd_udb_persist();   /* v0.75 — cross-boot proof */
    else if (!kstrcmp(argv[0], "udbstat"))    cmd_udb_stat();
    else if (!kstrcmp(argv[0], "appsstress")) cmd_apps_stress();
    else if (!kstrcmp(argv[0], "posixstress")) cmd_posix_stress();
    else if (!kstrcmp(argv[0], "toolchainstress")) cmd_selfhost_test();
    else if (!kstrcmp(argv[0], "cc")) cmd_cc(argc, argv);
    else if (!kstrcmp(argv[0], "compilerstress")) cmd_compiler_stress();
    else if (!kstrcmp(argv[0], "pipestress")) cmd_pipe_stress();
    else if (!kstrcmp(argv[0], "langstress")) cmd_lang_stress();
    else if (!kstrcmp(argv[0], "threadstress")) cmd_thread_stress();
    else if (!kstrcmp(argv[0], "pthreadsmp")) cmd_pthreads_smp();
    else if (!kstrcmp(argv[0], "sigstress")) cmd_sig_stress();
    else if (!kstrcmp(argv[0], "mmapstress")) cmd_mmap_stress();
    else if (!kstrcmp(argv[0], "shmstress")) cmd_shm_stress();
    else if (!kstrcmp(argv[0], "epollstress")) cmd_epoll_stress();
    else if (!kstrcmp(argv[0], "netepollstress")) cmd_netepoll_stress();
    else if (!kstrcmp(argv[0], "mmapfilestress")) cmd_mmapfile_stress();
    else if (!kstrcmp(argv[0], "tcpstress")) cmd_tcp_stress();
    else if (!kstrcmp(argv[0], "vfscrashwrite")) {
        /* Manual, one-shot half of the genuine cross-QEMU-reboot journal proof
         * (see the probe in cmd_cas()): commit this write's journal entry,
         * then halt WITHOUT ever calling SYS_VFS_SYNC or shutting down
         * cleanly — simulating real power loss mid-write. A SEPARATE later
         * boot against the same disk image is what proves recovery, not
         * this process. Not part of the automated suite by design. */
        static const uint8_t crashpat2[24] = "CROSS-REBOOT-JOURNAL-OK";
        vfs_write_file("vfs-reboot-test", crashpat2, sizeof crashpat2);
        kputs("[vfs    ] vfscrashwrite: journal-committed 'vfs-reboot-test', halting WITHOUT sync (simulated power loss)\n");
        for (;;) __asm__ volatile("cli; hlt");
    }
    else if (!kstrcmp(argv[0], "mem"))    multiboot_scan(g_mb_info, true);
    else if (!kstrcmp(argv[0], "uptime")) kprintf("%u.%u s since boot (%u ticks)\n",
                                                  g_ticks / 100, (g_ticks % 100) / 10, g_ticks);
    else if (!kstrcmp(argv[0], "mint") && argc == 4)
        cap_mint(argv[1], argv[2], (argv[3][0] == 'W' || argv[3][0] == 'w') ? 'W' : 'R');
    else if (!kstrcmp(argv[0], "revoke") && argc == 2) {
        int s = 0;
        for (char *p = argv[1]; *p >= '0' && *p <= '9'; p++) s = s * 10 + (*p - '0');
        cap_revoke(s);
    }
    else if (!kstrcmp(argv[0], "panic")) {
        kputs("[kernel ] triggering a deliberate invalid-opcode fault...\n");
        __asm__ volatile("ud2");
    }
    else if (!kstrcmp(argv[0], "reboot")) {
        kputs("[kernel ] warm reboot\n");
        outb(0x64, 0xFE);
    }
    else if (!kstrncmp(argv[0], "mint", 4) || !kstrncmp(argv[0], "revoke", 6))
        kputs("usage: mint <holder> <resource> <R|W>   |   revoke <slot>\n");
    else
        kprintf("unknown command '%s' — try 'help'\n", argv[0]);
}

static void shell_run(void) {
    char line[80];
    uint32_t len = 0;
    /* v0.75: the precondition of the resume-point race, counted for the whole
     * boot. Non-zero means BSP thread switches DID happen with a ring-3
     * excursion live on this core — which before sched_switch_to saved the
     * resume context was the corruption that produced an intermittent #13 at a
     * non-canonical RIP. Printed unconditionally so the number is evidence in
     * every log rather than something a future reader has to re-derive. */
    kprintf("[excur  ] BSP thread switches during a live ring-3 excursion: %u\n",
            g_excur_switch);
    /* v0.75: the three rank-bookkeeping counters, printed every boot so a
     * verification run reads them straight out of the log instead of inferring
     * them from the absence of warnings. All three must be 0. */
    kprintf("[klock  ] rank violations=%u underflow=%u mismatch=%u\n",
            g_rank_violations, g_rank_underflow, g_rank_mismatch);
#ifdef KERNEL_DEBUG
    /* v0.81: the ownership checks report their totals for the same reason the
     * rank counters do — so a run states ZERO rather than merely not printing a
     * warning. Without this line a build with the checks compiled OUT and a build
     * with them compiled in and clean produce identical logs, and this project
     * has already been misled once by grepping for a string no code could emit. */
    kprintf("[klock  ] KERNEL_DEBUG: self-deadlock/wrong-owner=%u syscall+thread locks=%u\n",
            g_lock_selfdeadlock, g_lock_mixed_ctx);
#else
    kputs("[klock  ] KERNEL_DEBUG off: ownership and context checks NOT compiled in\n");
#endif
    /* v0.75: the sys_connect counters. apyield is COVERAGE — how often an AP
     * actually entered the retransmit loop, so a run reporting 0 has not
     * exercised the AP path and its clean result says nothing about it. stale
     * is a FAULT count: slots reissued underneath the loop and refused.
     *
     * Printed here rather than left as a variable only a debugger could read.
     * A counter nothing prints is not instrumentation — the first -smp 4 matrix
     * of this fix grepped its logs for a stale count that no code could ever
     * emit, and read the resulting zeroes as evidence.
     *
     * Caveat this cannot fix: a HUNG boot never reaches this line, so these
     * numbers describe surviving boots only. */
    kprintf("[connect] apyield=%u stale=%u\n", g_connect_ap_yield, g_connect_stale);
#ifdef FORK_FUNNEL_REPRO
    /* Loud, unmissable, and in the LOG rather than in someone's memory of which
     * command they ran. A reproducer kernel that looks like a normal one has
     * already been read as a clean baseline once in this project. */
    kputs("\n*** BUILT WITH FORK_FUNNEL_REPRO — fork enqueues to cpu0 unconditionally.\n");
    kputs("*** This is v0.75's DEFECT, restored on purpose. NOT a release kernel.\n");
#endif
#ifdef FUTEX_RACE_REPRO
    kputs("\n*** BUILT WITH FUTEX_RACE_REPRO — thread_join tests thr_done OUTSIDE the\n");
    kputs("*** futex lock and arms separately, with the window widened by 2 ticks, and\n");
    kputs("*** the park deadline shortened to 2 s. This is the pre-v0.78 lost-wakeup\n");
    kputs("*** defect, restored on purpose. NOT a release kernel.\n");
#endif
    kputs("\nType 'help' for commands, 'demo' for the capability walk-through.\n");
    kputs("outrun> ");
    for (;;) {
        xhci_poll_hid();                              /* v0.51: real USB HID, same sinks as PS/2 */
        int c = kbd_getc_nonblock();                  /* VM display / bare metal */
        if (c < 0) c = serial_getc_nonblock();        /* Proxmox serial console  */
        if (c < 0) { sched_yield();                   /* keep ring-3 threads live */
                     __asm__ volatile("hlt"); continue; }
        if (c == '\r') c = '\n';
        if (c == '\b' || c == 127) {
            if (len) { len--; kputc('\b'); }
            continue;
        }
        if (c == '\n') {
            kputc('\n');
            line[len] = 0;
            shell_exec(line);
            len = 0;
            kputs("outrun> ");
            continue;
        }
        if (len < sizeof line - 1 && c >= 32 && c < 127) {
            line[len++] = (char)c;
            kputc((char)c);
        }
    }
}

/* ---- Entry ---------------------------------------------------------------------------------------- */
void __attribute__((no_stack_protector)) kernel_main(uint64_t mb_info) {
    /* v0.39: the compiler's stack guard lives at %gs:CPUL_CANARY, so the BSP's
     * GS base must point at its cpu_local before ANY protected function runs.
     * (kernel_main itself is excluded: its prologue predates this wrmsr.)     */
    wrmsr(0xC0000101, (uint64_t)&g_cpu[0]);
    g_cpu[0].idx = 0;
    g_gs_ready = 1;
    canary_init();                          /* seed per-CPU guard words first  */
    serial_init();
    vga_clear();
    g_mb_info = mb_info;

    kputs("\n");
    kputs("  ....................................................................\n");
    kputs("  :   OUTRUN OS  --  bare-metal kernel " KERNEL_VERSION "                   :\n");
    kputs("  :   Assembly bootstrap -> x86_64 long mode -> freestanding C core  :\n");
    kputs("  ....................................................................\n\n");

    kprintf("[kernel ] long mode active, kernel at 1 MiB, first GiB identity-mapped\n");

    /* Interrupts */
    for (int v = 0; v < 48; v++) {
        static uint64_t handlers[48];
        (void)handlers;
    }
    {
        uint64_t h[52] = {
            ISR_ADDR(0),ISR_ADDR(1),ISR_ADDR(2),ISR_ADDR(3),ISR_ADDR(4),ISR_ADDR(5),
            ISR_ADDR(6),ISR_ADDR(7),ISR_ADDR(8),ISR_ADDR(9),ISR_ADDR(10),ISR_ADDR(11),
            ISR_ADDR(12),ISR_ADDR(13),ISR_ADDR(14),ISR_ADDR(15),ISR_ADDR(16),ISR_ADDR(17),
            ISR_ADDR(18),ISR_ADDR(19),ISR_ADDR(20),ISR_ADDR(21),ISR_ADDR(22),ISR_ADDR(23),
            ISR_ADDR(24),ISR_ADDR(25),ISR_ADDR(26),ISR_ADDR(27),ISR_ADDR(28),ISR_ADDR(29),
            ISR_ADDR(30),ISR_ADDR(31),ISR_ADDR(32),ISR_ADDR(33),ISR_ADDR(34),ISR_ADDR(35),
            ISR_ADDR(36),ISR_ADDR(37),ISR_ADDR(38),ISR_ADDR(39),ISR_ADDR(40),ISR_ADDR(41),
            ISR_ADDR(42),ISR_ADDR(43),ISR_ADDR(44),ISR_ADDR(45),ISR_ADDR(46),ISR_ADDR(47),
            ISR_ADDR(48),ISR_ADDR(49),                 /* v0.35: IPI vectors    */
            ISR_ADDR(50),ISR_ADDR(51),                 /* v0.39 preempt, v0.40 slice */
        };
        for (int v = 0; v < 52; v++) idt_set(v, h[v]);
        struct idtr idtr = { sizeof(idt) - 1, (uint64_t)idt };
        idt_load(&idtr);
    }
    pic_remap();
    pit_init();
    __asm__ volatile("sti");
    kprintf("[kernel ] IDT loaded (52 vectors incl. IPI 48-50 + slice tick 51), PIC remapped, PIT @ 100 Hz, IRQs on\n");
    kprintf("[kernel ] consoles: VGA text + COM1 serial (115200 8N1) — both live\n");

    multiboot_scan(mb_info, true);

    kprintf("[kernel ] capability table initialized (%d slots, kernel-owned)\n", MAX_CAPS);

    /* Capture the boot PML4 so process address spaces can share the low        */
    /* identity map (keeping kernel code/stack/IDT mapped after a CR3 switch),   */
    /* then run the real-paging passthrough demonstration once at boot.         */
    kernel_cr3 = read_cr3();
    kprintf("[kernel ] paging: boot PML4 @ phys %X; process frame pool from 16 MiB\n",
            kernel_cr3);
    harden_kernel_wx();
    kprintf("[kernel ] W^X enforced: kernel .text R+X, all other pages RW+NX\n");
    g_sweep.enabled = 1;                    /* start continuous background PTE audit */
    kprintf("[sweep  ] descriptor-table integrity sweep armed: %d entries/tick @ 100 Hz\n\n",
            SWEEP_BATCH);
    cmd_passthrough();
    iommu_init();

    /* Discover real hardware on the PCI bus (registers the virtio NIC's MMIO  */
    /* window as a capability-gated device), then enable ring 3 and run the    */
    /* passthrough as a real SYSCALL trap from an unprivileged ELF process.    */
    kputs("\n");
    pci_init();
    sched_init();
    cpp_ring_selftest();
    cmd_cas();
    cmd_vfs();
    /* v0.75 step 6: the user database comes off the volume as soon as there IS
     * a volume, and before anything can authenticate against it. Placed after
     * cmd_vfs() because the image is stored as VFS files, and before every
     * suite because authstrs manipulates the same table. */
    udb_load();
    /* v0.80: WHAT THE KDF ACTUALLY COSTS ON THIS MACHINE, every boot.
     *
     * The scrypt parameters were chosen from an in-guest measurement rather than
     * from host timings, because this environment is TCG-only and a constant
     * picked on an idle native machine is the mistake this project has made more
     * than any other. Printing it keeps the choice observable instead of
     * historical: if the host, the emulator or the parameters change, the number
     * moves and somebody can see it.
     *
     * Four derivations, not one: g_ticks is 100 Hz, so a single derivation of a
     * few tens of milliseconds would round to one or two ticks and tell us
     * almost nothing about which side of a threshold it sits on. */
    {
        static const uint8_t tsalt[UDB_SALT_LEN] = { 0 };
        uint8_t th[UDB_HASH_LEN];
        uint64_t t0 = g_ticks;
        for (int i = 0; i < 4; i++) udb_kdf_scheme(UDB_KDF_SCRYPT, "benchmark", tsalt, th);
        uint64_t dt = g_ticks - t0;
        uint64_t t1 = g_ticks;
        for (int i = 0; i < 4; i++) udb_kdf_scheme(UDB_KDF_PBKDF2, "benchmark", tsalt, th);
        uint64_t dp = g_ticks - t1;
        kprintf("[udb    ] KDF cost: scrypt(N=%u r=%u p=%u, %u KiB) %u ds/4 = ~%u ms each; "
                "PBKDF2(c=%u) %u ds/4\n",
                (uint64_t)UDB_SCRYPT_N, (uint64_t)UDB_SCRYPT_R, (uint64_t)UDB_SCRYPT_P,
                (uint64_t)(UDB_SCRYPT_SCRATCH / 1024), dt, (dt * 10) / 4,
                (uint64_t)UDB_KDF_ROUNDS, dp);
    }
    cmd_sched();
    cmd_net();
    cmd_timestream();
    cmd_validate();
    cmd_invariants();
    usermode_init();        /* user GDT segments + TSS + SYSCALL MSRs (needed for ring 3) */
    smp_init();             /* v0.35: boot every core (needs the kernel GDT above) */
#ifdef POSIX_ITER
    /* Fast-iteration build (make EXTRA=-DPOSIX_ITER): run ONLY the milestone's
     * own suite. Everything it needs — CAS/VFS, ring 3, SMP — is already up.
     * Never defined in a release build; the full matrix below is the gate.   */
    cmd_posix_stress();
    shell_run();
#endif
    cmd_stress();
    cmd_fuzz();
    cmd_sweep();
    cmd_smp();              /* v0.35: cross-core protocol verification            */
    cmd_parallel();         /* v0.36: work-stealing parallel job across cores     */
    cmd_audit();            /* v0.37: parallel page-table integrity audit         */
    /* v0.66: mmapfilestrs' fixture is created HERE, before the battery, not
     * inside the suite. The VFS directory is 64 entries and the toolchain
     * suites spend the last of them mid-boot — by suite 41 there is no room
     * left, which is a pre-existing headroom problem (v0.60 onward) and not
     * something a new suite should discover for itself at the point of use.
     * Creating it early also keeps the fixture out of every earlier suite's
     * way: it is written once and only ever read or mapped afterwards. */
    {
        static uint8_t m66seed[M66_FIXTURE_LEN];
        for (uint32_t i = 0; i < M66_FIXTURE_LEN; i++) m66seed[i] = (uint8_t)((i * 7 + 3) & 0xFF);
        if (vfs_write_file("m66dat", m66seed, M66_FIXTURE_LEN) < 0)
            kputs("[vfs    ] WARNING: could not seed 'm66dat' — mmapfilestrs will report it\n");
    }
    cmd_mcsched();          /* v0.38: an AP autonomously runs a ring-3 thread      */
    cmd_mcq();              /* v0.39: per-CPU queues, stealing, concurrent ring 3  */
    cmd_mcpre();            /* v0.39: IPI preemption + cross-core context migration */
    cmd_slice();            /* v0.40: AP-local LAPIC timer round-robin time-slicing */
    cmd_cio();              /* v0.41: BSP + APs concurrently inside the VFS/CAS/surfaces */
    cmd_smp_stress();       /* v0.43: mixed syscall/VFS/compositor workload, every core   */
    cmd_dma_stress();       /* v0.44: real DMA/IOMMU grants revoked across genuine exit    */
    cmd_leakcheck();        /* v0.42: heavy spawn/destroy proves 100% frame reclamation  */
    cmd_kproc_stress();     /* v0.45: 200-cycle kproc/descriptor recycle stress          */
    cmd_ipc_stress();       /* v0.46: capability-gated IPC fd/shmem handoff, sender/receiver churn */
    cmd_vfio_stress();      /* v0.47: VFIO BAR mapping + routed interrupt wait, driver churn        */
    cmd_vfs_stress();       /* v0.48: VFS journaling, unlink/reclamation, multi-volume mounts       */
    cmd_gpu_stress();       /* v0.50: virtio-gpu 2D resource/scanout/flush churn, incl. client faults */
    cmd_audio_stress();     /* v0.51: virtio-sound PCM configure/write churn, incl. client faults */
    cmd_net_stress();       /* v0.52: ring-3 datagram-socket bind/connect/send/recv churn, incl. client faults */
    cmd_users_stress();     /* v0.72: process credentials, file ownership and permission enforcement */
    cmd_wimp_stress();      /* v0.53: ring-3 WIMP window create/manage/close churn + WM logic, incl. client faults */
    cmd_apps_stress();      /* v0.54: concurrent ring-3 GUI apps (terminal/sysmon/filer), incl. app crashes */
    cmd_posix_stress();     /* v0.55: fork/exec chains, signal frames, pthread mutexes under SMP */
    /* v0.75: authstrs is an ORDINARY member of this sequence again. v0.74
     * removed it after it made posixstrs fail 4 of its 12 assertions under
     * -smp 4 on SeaBIOS, with the mechanism unknown; this milestone found a real
     * scheduler defect on that path, and it had nothing to do with
     * authentication. sys_fork enqueued every forked child onto cpu
     * 0's run queue no matter which core called fork, so a child could sit in a
     * queue its waiting parent never drained until the parent's waitpid budget
     * expired (see the note at the rq_push_any call in sys_fork). authstrs was
     * never the bug — it was the load that exposed one, which is what a stress
     * suite is FOR. Removing it was a mitigation; restoring it is the acceptance
     * test, because it is the only configuration known to trigger the race.
     * See ROADMAP-0.75.0.md. The v0.74 record follows, kept because it is the
     * account of what was eliminated and at what cost:
     *
     * v0.74: authstrs was DELIBERATELY ABSENT from this sequence. It was a shell
     * command — `authstress` — and this comment is why, because a suite missing
     * from the regression boot looks like an oversight and would be silently
     * "fixed" by the next person to notice it.
     *
     * Compiled into the boot sequence, authstrs made posixstrs fail 4 of its 12
     * assertions under `-smp 4` on SeaBIOS, and only there — uniprocessor and
     * smp4-iommu were clean in every run. The symptom was a forked child
     * reporting the wrong parent through getppid and its parent's waitpid then
     * timing out, in rounds 0 and 2 but not round 1: a race, not a broken rule.
     *
     * Ruled out, each by its own boot rather than by argument:
     *   - the v0.74 credential model. Every kernel change present, this suite
     *     merely not called: posixstrs 12/12.
     *   - kproc slot recycling. Two no-op spawns marked recyclable exactly as
     *     this suite leaves them, nothing else: posixstrs 12/12.
     *   - set-id on exec. Zero set-id events fired in the entire failing boot.
     *   - suite ORDER. Moved after posixstrs — so posixstrs completes before
     *     authstrs begins — and posixstrs failed anyway. Whatever the coupling
     *     is, it is not sequential.
     *   - the host. v0.73 is 12/12 here twice, on a fast host and on one
     *     running ~4x slower.
     *
     * Across eight runs: 0 failures in 4 builds where this suite does not
     * execute, 3 failures in 4 where it does. The two surviving explanations
     * are CONFOUNDED and cannot be separated by any build made so far — the
     * suite's runtime cost, and the ~8KB the binary grows when dead-code
     * elimination stops discarding it. Every build that runs authstrs is also
     * every build that is 8KB larger, and a layout-sensitive timing race would
     * explain why running posixstrs first did not help.
     *
     * SO THE MECHANISM IS UNKNOWN, stated plainly rather than dressed up.
     * Keeping the suite out of the boot path is a MITIGATION, not a fix: it
     * makes the three-config matrix honest again while leaving the real defect
     * — an intermittent race in posixstrs's fork/waitpid path that nineteen
     * releases never perturbed — exactly where it was found, for a milestone
     * that can afford to chase it. `authstress` runs the suite in full at any
     * prompt, and it passes 35/35 on all three configurations.
     * See CHANGELOG-0.74.0.md. */
    /* v0.75: BEFORE authstrs, deliberately. shastrs proves the primitive against
     * published vectors; authstrs exercises the KDF built on top of one. Ordering
     * them this way means that once udb_kdf() is pointed at SHA-256, a red boot
     * reads in the right order — if shastrs is green and authstrs is red, the
     * hash is fine and the KDF is not. */
    cmd_sha_stress();       /* v0.75: SHA-256 vs FIPS 180-4 / CAVP vectors */
    cmd_auth_stress();      /* v0.74: password KDF, account lockout, credential transitions */
    cmd_selfhost_test();    /* v0.56: author -> compile -> run, natively (no host toolchain)     */
    cmd_compiler_stress();  /* v0.57: language completeness + what the compiler must REFUSE      */
    cmd_pipe_stress();      /* v0.59: pipes, redirection, and a ring-3 shell this system built   */
    cmd_lang_stress();      /* v0.60: sizeof/for-init/switch/unsigned + omake driving occ natively */
    cmd_thread_stress();    /* v0.61: ring-3 threads across cores, futex blocking, kernel join     */
    cmd_pthreads_smp();     /* v0.62: pthread mutex contention + condition variable across cores   */
    cmd_sig_stress();       /* v0.62: signal masks, dispositions, process-group delivery           */
    cmd_mmap_stress();      /* v0.63: demand-zero paging, mprotect, munmap                         */
    cmd_shm_stress();       /* v0.63: copy-on-write fork and zero-copy shared memory               */
    cmd_epoll_stress();     /* v0.64: event-driven readiness, eventfd counters, EOF reporting      */
    cmd_netepoll_stress();  /* v0.65: non-blocking sockets multiplexed with epoll                  */
    cmd_mmapfile_stress();  /* v0.66: file-backed mappings, shared pages, writeback                */
    cmd_iommu();
    cmd_capdma();
    cmd_nicdriver();
    /* v0.68: tcpstrs runs AFTER capdma, deliberately. capdma proves a confined
     * device is BLOCKED by the IOMMU when it attempts kernel DMA, and it needs
     * a quiescent NIC transmit queue to produce that fault — which is exactly
     * why netstrs has never sent a real frame, and says so in v0.52's
     * changelog. v0.68 gave tcpstrs one genuine wire transmit, and that single
     * SYN was enough to make capdma's confined-DMA assertion fail under VT-d
     * while both BIOS configurations stayed clean. Ordering is the fix: the
     * suite that needs silence goes first. */
    cmd_tcp_stress();       /* v0.68: TCP handshake, byte stream, FIN, and the wire codec */
    mouse_init();
    fb_init();
    cmd_gfx();
    cmd_surface();        /* spawns the surface app as a first-class thread     */
    cmd_threads();        /* v0.31: thread model verification suite             */
    cmd_flip();           /* v0.32: double-buffer page-flip / tearing suite     */
    cmd_cursor();
    cmd_kinetic();
    cmd_canvas(300, "/zoom fit\n");
    cmd_surfin();         /* clicks routed + app reacts INSIDE this single pass */
    cmd_keys();           /* v0.33: keyboard routed to the focused app          */
    cmd_canvas(120, 0);   /* recomposite — the hit markers persist              */
    cmd_usermode();

    shell_run();
}
